// ============================================================================
// JTAG TAP controller, IEEE 1149.1
// 16-state FSM in TCK domain; IDCODE / BYPASS / USER data registers.
// irq (clk domain): one-cycle pulse after each USER register update.
// Style follows classic OpenCores jtag/openjtag TAP cores.
// Auto-generated by gen_framework.py -- Apache-2.0
// ============================================================================
module JTAG_top #(
  parameter logic [31:0] IDCODE = 32'h1CAF_0001
)(
  input  logic clk,
  input  logic rst_n,
  input  logic tck,
  input  logic tms,
  input  logic tdi,
  input  logic trst_n,
  output logic tdo,
  output logic irq
);
  // ---------------- TAP FSM (TCK domain) ----------------
  typedef enum logic [3:0] {
    TLR = 4'd0,  RTI,      SEL_DR, CAP_DR,
    SH_DR,       EX1_DR,   PAUSE_DR, EX2_DR,
    UPD_DR,      SEL_IR,   CAP_IR,   SH_IR,
    EX1_IR,      PAUSE_IR, EX2_IR,   UPD_IR
  } tap_t;
  tap_t tap_q;

  always_ff @(posedge tck or negedge trst_n) begin
    if (!trst_n) tap_q <= TLR;
    else case (tap_q)
      TLR:      tap_q <= tms ? TLR     : RTI;
      RTI:      tap_q <= tms ? SEL_DR  : RTI;
      SEL_DR:   tap_q <= tms ? SEL_IR  : CAP_DR;
      CAP_DR:   tap_q <= tms ? EX1_DR  : SH_DR;
      SH_DR:    tap_q <= tms ? EX1_DR  : SH_DR;
      EX1_DR:   tap_q <= tms ? UPD_DR  : PAUSE_DR;
      PAUSE_DR: tap_q <= tms ? EX2_DR  : PAUSE_DR;
      EX2_DR:   tap_q <= tms ? UPD_DR  : SH_DR;
      UPD_DR:   tap_q <= tms ? SEL_DR  : RTI;
      SEL_IR:   tap_q <= tms ? TLR     : CAP_IR;
      CAP_IR:   tap_q <= tms ? EX1_IR  : SH_IR;
      SH_IR:    tap_q <= tms ? EX1_IR  : SH_IR;
      EX1_IR:   tap_q <= tms ? UPD_IR  : PAUSE_IR;
      PAUSE_IR: tap_q <= tms ? EX2_IR  : PAUSE_IR;
      EX2_IR:   tap_q <= tms ? UPD_IR  : SH_IR;
      UPD_IR:   tap_q <= tms ? SEL_DR  : RTI;
    endcase
  end

  // ---------------- instruction + data registers ----------------
  // TDI/TMS are sampled and the chains shift on rising TCK; TDO changes on
  // falling TCK (IEEE 1149.1), so the master samples a stable TDO on the
  // next rising edge. Test-Logic-Reset selects IDCODE (the device has one).
  localparam logic [3:0] IR_IDCODE = 4'b0001;
  localparam logic [3:0] IR_USER   = 4'b0010;

  logic [3:0]  ir_q, sh_ir;
  logic        sh_byp;
  logic [7:0]  user_q, sh_user;
  logic [31:0] sh_id;
  logic        upd_tgl;                   // toggles on every USER update

  always_ff @(posedge tck or negedge trst_n) begin
    if (!trst_n) begin
      ir_q <= IR_IDCODE; sh_ir <= '0;
    end else begin
      case (tap_q)
        TLR:     ir_q  <= IR_IDCODE;
        CAP_IR:  sh_ir <= 4'b0101;              // capture pattern (LSBs 01)
        SH_IR:   sh_ir <= {tdi, sh_ir[3:1]};
        UPD_IR:  ir_q  <= sh_ir;
        default: ;
      endcase
    end
  end

  always_ff @(posedge tck or negedge trst_n) begin
    if (!trst_n) begin
      sh_byp <= 1'b0; sh_user <= '0; sh_id <= '0; user_q <= '0; upd_tgl <= 1'b0;
    end else begin
      case (tap_q)
        CAP_DR:
          case (ir_q)
            IR_IDCODE: sh_id   <= IDCODE;
            IR_USER:   sh_user <= user_q;
            default:   sh_byp  <= 1'b0;         // BYPASS (1111) and unused opcodes
          endcase
        SH_DR:
          case (ir_q)
            IR_IDCODE: sh_id   <= {tdi, sh_id[31:1]};
            IR_USER:   sh_user <= {tdi, sh_user[7:1]};
            default:   sh_byp  <= tdi;
          endcase
        UPD_DR:
          if (ir_q == IR_USER) begin
            user_q  <= sh_user;
            upd_tgl <= ~upd_tgl;
          end
        default: ;
      endcase
    end
  end

  wire dr_lsb = (ir_q == IR_IDCODE) ? sh_id[0] :
                (ir_q == IR_USER)   ? sh_user[0] : sh_byp;
  logic tdo_q;
  always_ff @(negedge tck or negedge trst_n) begin
    if (!trst_n)              tdo_q <= 1'b0;
    else if (tap_q == SH_IR)  tdo_q <= sh_ir[0];
    else if (tap_q == SH_DR)  tdo_q <= dr_lsb;
    else                      tdo_q <= 1'b0;   // inactive outside Shift states
  end
  assign tdo = tdo_q;

  // ---------------- irq: USER register updated (clk domain) ----------------
  logic [2:0] upd_s;
  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) upd_s <= '0;
    else        upd_s <= {upd_s[1:0], upd_tgl};
  end
  assign irq = upd_s[2] ^ upd_s[1];

endmodule
